CREATE TABLE IF NOT EXISTS mes_platform_line (line_code VARCHAR(32) PRIMARY KEY, display_name VARCHAR(128) NOT NULL, area_path VARCHAR(256)); CREATE TABLE IF NOT EXISTS mes_oee_shift (id UUID PRIMARY KEY, line_code VARCHAR(32) NOT NULL, shift_label VARCHAR(64) NOT NULL, planned_minutes INTEGER NOT NULL, downtime_minutes INTEGER NOT NULL, ideal_cycle_sec INTEGER NOT NULL, total_units INTEGER NOT NULL, good_units INTEGER NOT NULL);
